#!/usr/bin/env node
// Temporarily replace ignored dist output for a signed-in, local host pass.
// Restore the normal plugin with npm run build after validation.
import { build } from "vite";
import { readFile, writeFile } from "node:fs/promises";
import { extname, resolve } from "node:path";
import { deflateSync } from "node:zlib";

function png(index) {
  const crc = (data) => {
    let value = 0xffffffff;
    for (const byte of data) { value ^= byte; for (let bit = 0; bit < 8; bit++) value = value >>> 1 ^ (value & 1 ? 0xedb88320 : 0); }
    return (value ^ 0xffffffff) >>> 0;
  };
  const chunk = (name, data) => { const type = Buffer.from(name); const size = Buffer.alloc(4); size.writeUInt32BE(data.length); const sum = Buffer.alloc(4); sum.writeUInt32BE(crc(Buffer.concat([type, data]))); return Buffer.concat([size, type, data, sum]); };
  const header = Buffer.alloc(13); header.writeUInt32BE(1, 0); header.writeUInt32BE(1, 4); header[8] = 8; header[9] = 6;
  const data = Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk("IHDR",header),chunk("IDAT",deflateSync(Buffer.from([0,index * 19 % 256,index * 37 % 256,index * 53 % 256,255]))),chunk("IEND",Buffer.alloc(0))]);
  return `data:image/png;base64,${data.toString("base64")}`;
}

// Real extractor output for a checked-in fixture; `fixture <viewport>` imports one of its scenes.
const fixtureFile = process.env.PHASE5_FIXTURE || "transforms.html";
const evidence = JSON.parse(await readFile(resolve("src/capture/fixtures/baselines/scene-evidence.json"), "utf8"));
const mediaTypes = { ".svg": "image/svg+xml", ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".gif": "image/gif", ".webp": "image/webp" };
// The baselines captured assets from a local fixture server; inline them so the host pass needs no server.
async function inlineFixtureAsset(asset) {
  const name = asset.url && new URL(asset.url).pathname.split("/").pop();
  const type = name && mediaTypes[extname(name)];
  if (!type) return asset;
  try { return { id: asset.id, dataUrl: `data:${type};base64,${(await readFile(resolve("src/capture/fixtures/assets", name))).toString("base64")}`, mimeType: type }; }
  catch { return asset; }
}
const fixtureScenes = await Promise.all((evidence.fixtures.find((fixture) => fixture.file === fixtureFile)?.viewports ?? [])
  .map(async ({ scene }) => ({ ...scene, assets: await Promise.all(scene.assets.map(inlineFixtureAsset)) })));
const result = await build({ configFile: false, logLevel: "error", define: { FIXTURE_SCENES: JSON.stringify(fixtureScenes), LIVE_IMAGES: JSON.stringify(Array.from({ length: 120 }, (_, index) => png(index))) }, build: { write: false, lib: { entry: resolve("scripts/lib/importer-live-harness.ts"), formats: ["iife"], name: "ImporterHostValidation" } } });
const output = (Array.isArray(result) ? result : [result]).flatMap((entry) => entry.output);
const bundle = output.find((entry) => entry.type === "chunk")?.code;
if (!bundle) throw new Error("Empty validation bundle.");
await writeFile("dist/plugin.js", bundle);
await writeFile("dist/index.html", `<!doctype html><title>Importer host validation</title><p>Temporary local validation harness. Restore the plugin with npm run build.</p><pre id="result">Ready</pre><script>
addEventListener("message", event => {
  if (event.source !== parent) return;
  if (event.data?.phase5Command) parent.postMessage(event.data.phase5Command, "*");
  else { document.getElementById("result").textContent = JSON.stringify(event.data); parent.postMessage({ phase5Result: event.data }, "*"); }
});
</script>`);
process.stdout.write("Local validation harness built. Reopen the installed local plugin; run npm run build to restore it.\n");
#!/usr/bin/env node
/**
 * Regenerate the checked-in browser references for the importer fixtures.
 *
 * No browser automation package is needed: Chrome's remote-debugging pipe is
 * sufficient for real layout, font readiness checks, screenshots, and the
 * same self-contained extractor script used by the capture sandbox.
 */
import { createHash } from "node:crypto";
import { createServer } from "node:http";
import { mkdtemp, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, extname, join, normalize, relative, resolve, sep } from "node:path";
import { spawn } from "node:child_process";
import { tmpdir } from "node:os";
import typescript from "typescript";
import { CdpPipe, closeChrome } from "./lib/chrome.mjs";

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const fixtureDirectory = join(repositoryRoot, "src", "capture", "fixtures");
const outputDirectory = join(fixtureDirectory, "baselines");
const extractorPath = join(repositoryRoot, "src", "capture", "extractor.ts");
const fontFamily = "DejaVu Sans";
// Keep scene asset URLs reproducible in checked-in evidence. The interactive
// comparison server intentionally uses the adjacent port 4174 instead.
const baselinePort = 4175;
const fixtureFiles = [
  "background-images.html",
  "overflow-clipping.html",
  "color-opacity.html",
  "stacking-contents-whitespace.html",
  "asset-failures.html",
  "transforms.html",
  "per-side-borders.html"
];
const fixtureAssetDirectory = join(fixtureDirectory, "assets");
const viewports = [
  // Keep this synchronized with DEFAULT_VIEWPORTS in src/shared/contracts.ts.
  // Screenshot filenames retain their established width-based suffixes below.
  { id: "desktop", name: "Desktop", width: 1440, height: 900 },
  { id: "tablet", name: "Tablet", width: 768, height: 1024 },
  { id: "mobile", name: "Mobile", width: 390, height: 844 }
];

const mimeTypes = {
  ".css": "text/css; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".svg": "image/svg+xml",
  ".ttf": "font/ttf",
  ".woff": "font/woff",
  ".woff2": "font/woff2"
};

function sha256(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

