    const ratioY = viewport.height / viewBox.height;
    const ratio = aligned![3] === "slice" ? Math.max(ratioX, ratioY) : Math.min(ratioX, ratioY);
    const width = viewBox.width * ratio;
    const height = viewBox.height * ratio;
